        type_arguments,
        args,
        bindings,
        path,
        span,
    } = call;
    let name = op.name();
    if (if op == crate::vec_ops::VecOp::StrAt {
        !type_arguments.is_empty() || function.instance().is_some()
    } else {
        type_arguments.len() != 1
    }) || args.len() != op.arity()
    {
        return Err(resolver.error(
            "SPX-H006",
            format!("invalid vector operation `{name}` call shape"),
            span,
        ));
